from pathlib import Path
import sqlite3,json,re
w=Path(__file__).resolve().parent;c=sqlite3.connect('file:'+str(w/'input/index.sqlite3')+'?mode=ro',uri=True);c.row_factory=sqlite3.Row
rows=[dict(r) for r in c.execute("SELECT * FROM segments WHERE path LIKE 'input/sources/%'")];lookup={};bykey={(r['path'],r['anchor']):r for r in rows}
for d in rows:
 for m in re.findall(r'\[([A-Z]+[0-9]*(?:-[0-9]+)?)\]',d['quote']):lookup[m]=d
reports=json.loads((w/'input/report-ledger.json').read_text())
def makeev(d,marker):
 l=json.loads(d['locator']);src=d['path'].removeprefix('input/');src=src[:-3] if src.endswith(('.pdf.md','.docx.md')) else src
 return {'path':d['path'],'anchor':d['anchor'],'quote':d['quote'],'source_marker':marker,'original_source_file':src,'original_coordinate':{k:v for k,v in l.items() if k in ('original','original_sha256','page','member','xml_path','table','row','cell','paragraph_index_in_story')}}
def evidence(markers):
 out=[]
 for m in markers:
  if m.startswith('TABLE:'):
   _,rev,row=m.split(':');p='input/sources/'+{'V1':'01-specification-v1.docx.md','V2':'02-specification-v2.docx.md','X':'03-exception-annex.docx.md'}[rev]
   parent={'V1':'V1-02','V2':'V2-02','X':'X01'}[rev]
   for col in range(1,6):out.append(makeev(bykey[(p,f'docx-table-0001-r{int(row):04d}-c{col:04d}-p0001')],f'{parent}, table1 row{row} column{col}'))
  else:out.append(makeev(lookup[m],m))
 return out

def pr(t,target,rel='supports'):return {'module':'Audit','theorem':'Audit.'+t,'relation':rel,'target':target}
f=[]
